class Solution {
    public List<Integer> commonElements(int[] a, int[] b, int[] c) {
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length && k < c.length) {
            if (a[i] == b[j] && b[j] == c[k]) {
                if (result.isEmpty() || result.get(result.size() - 1) != a[i]) result.add(a[i]);
                i++; j++; k++;
            } else {
                int smallest = Math.min(a[i], Math.min(b[j], c[k]));
                if (a[i] == smallest) i++;    // the smallest can't be common
                if (b[j] == smallest) j++;
                if (c[k] == smallest) k++;
            }
        }
        return result;
    }
}

class Solution {
public:
    vector<int> commonElements(vector<int>& a, vector<int>& b, vector<int>& c) {
        vector<int> result;
        size_t i = 0, j = 0, k = 0;
        while (i < a.size() && j < b.size() && k < c.size()) {
            if (a[i] == b[j] && b[j] == c[k]) {
                if (result.empty() || result.back() != a[i]) result.push_back(a[i]);
                i++; j++; k++;
            } else {
                int smallest = min({a[i], b[j], c[k]});
                if (a[i] == smallest) i++;    // the smallest can't be common
                if (b[j] == smallest) j++;
                if (c[k] == smallest) k++;
            }
        }
        return result;
    }
};
